    public double findTotal() {
        double total = 0;
        for (double mark : marks) total += mark;
        return total;
    }
}

public class Test {
    // █ FILLED BY STUDENT: Define getMax(Student[] arr) — return name with highest total
    public static String getMax(Student[] arr) {
        Student s = arr[0];
        for (int i = 1; i < arr.length; i++)
            if (arr[i].findTotal() > s.findTotal()) s = arr[i];
        return s.getName();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Student[] arr = new Student[3];
        for(int i = 0; i < 3; i++){
            String name = sc.next();
            double[] m = {sc.nextDouble(), sc.nextDouble(), sc.nextDouble()};
            arr[i] = new Student(name, m);
        }
        System.out.println(getMax(arr));
    }
