import java.util.*;
class Vowels {
    private String text;
    private int count;

    // █ FILLED BY STUDENT: Define constructor — count vowels in text
    public Vowels(String text) {
        this.text = text;
        for (int i = 0; i < text.length(); i++)
            if (isVowel(text.charAt(i))) this.count++;
    }


    // █ FILLED BY STUDENT: Define copy constructor — copy text and count
    public Vowels(Vowels v) { this.text = v.text; this.count = v.count; }


    // █ FILLED BY STUDENT: return true if x is a,e,i,o,u
    public static boolean isVowel(char x) {
        switch(x) { case 'a': case 'e': case 'i': case 'o': case 'u': return true; }
        return false;
    }
    // █ FILLED BY STUDENT: Implement getOriginalText()
    public String getOriginalText() { return this.text; }
    // █ FILLED BY STUDENT: Implement getCount()
    public int getCount() { return this.count; }
    // █ FILLED BY STUDENT: replace every vowel with 'V', update this.text
    public void manipulate() {
        String m = "";
        for (int i = 0; i < this.text.length(); i++)
            m += isVowel(this.text.charAt(i)) ? "V" : this.text.charAt(i);
        this.text = m;
    }
}
public class MClass {
    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        String t = sc.nextLine();
        Vowels v1 = new Vowels(t);
        Vowels v2 = new Vowels(v1);
        System.out.println(v2.getCount());
        v2.manipulate();
        System.out.println(v2.getOriginalText());
        System.out.println(v1.getOriginalText());
    }
}

