import java.util.*;

abstract class StringOperations {
    public abstract String reverse(String s);
    public abstract int vowelCount(String s);
}

// █ FILLED BY STUDENT: StringReverse extends StringOperations and implements reverse(); reverse: iterate s backward, build result string
abstract class StringReverse extends StringOperations {
    public String reverse(String s) {
        String res = "";
        for (int i = s.length()-1; i >= 0; i--) res += s.charAt(i);
        return res;
    }
}


// █ FILLED BY STUDENT: UpdatedStrings extends StringReverse and implements vowelCount(); vowelCount: convert to lowercase, count a/e/i/o/u
class UpdatedStrings extends StringReverse {
    public int vowelCount(String s) {
        String str = s.toLowerCase(); int count = 0;
        for (int i = 0; i < str.length(); i++) {
            char c = str.charAt(i);
            if (c=='a'||c=='e'||c=='i'||c=='o'||c=='u') count++;
        }
        return count;
    }
}


class Example {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        UpdatedStrings str = new UpdatedStrings();
        System.out.println("Reverse of " + s + " is " + str.reverse(s));
        System.out.println("Vowel count of " + s + " is " + str.vowelCount(s));
    }
}

