import java.util.*;

// █ FILLED BY STUDENT: Define class Point<T extends Number>; fields T x,y; constructor; mid(); toString()
class Point<T extends Number> {
    T x, y;
    public Point(T x, T y) { this.x = x; this.y = y; }
    public Point<Double> mid(Point<? extends Number> o) {
        double x_ = (this.x.doubleValue() + o.x.doubleValue()) / 2;
        double y_ = (this.y.doubleValue() + o.y.doubleValue()) / 2;
        return new Point<Double>(x_, y_);
    }
    public String toString() { return "("+x+","+y+")"; }
}


public class Test {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Point<Integer> p1 = new Point<Integer>(sc.nextInt(), sc.nextInt());
        Point<Double> p2 = new Point<Double>(sc.nextDouble(), sc.nextDouble());
        Point<Double> p3 = p1.mid(p2);
        System.out.println(p3);
    }
}

