// █ FILLED BY STUDENT: Define class ComplexNum<T extends Number>; private T r, i; constructor; add(ComplexNum<?>); toString()
class ComplexNum<T extends Number> {
    private T r, i;
    public ComplexNum(T r, T i) { this.r=r; this.i=i; }
    public ComplexNum<Double> add(ComplexNum<?> c) {
        ComplexNum<Double> dc = new ComplexNum<Double>(0.0, 0.0);
        dc.r = this.r.doubleValue() + c.r.doubleValue();
        dc.i = this.i.doubleValue() + c.i.doubleValue();
        return dc;
    }
    public String toString() { return r.doubleValue() + " + " + i.doubleValue() + "i"; }
}


class FClass {
