import java.util.Scanner;

class AgeException extends Exception{AgeException(String m){super(m);}}
class CitizenshipException extends Exception{CitizenshipException(String m){super(m);}}
class RegistrationException extends Exception{RegistrationException(String m){super(m);}}
class FirstTimeVoterException extends Exception{FirstTimeVoterException(String m){super(m);}}

class Voter {
    private int age; private boolean isCitizen, isRegistered, firstTimeVoter;
    public Voter(int a,boolean c,boolean r,boolean f){age=a;isCitizen=c;isRegistered=r;firstTimeVoter=f;}
    public void validateVoter() {
        try {
            // █ FILLED BY STUDENT: throw appropriate exception for each condition; if firstTimeVoter use initCause for chaining
            if (age<18) throw new AgeException("You must be 18 or older to vote.");
            else if (!isCitizen) throw new CitizenshipException("Only citizens are allowed to vote.");
            else if (!isRegistered) {
                if (firstTimeVoter) {
                    RegistrationException re=new RegistrationException("You must be registered to vote");
                    re.initCause(new FirstTimeVoterException("First-time voters must register before voting."));
                    throw re;
                } else throw new RegistrationException("You must be registered to vote");
            } else System.out.println("You are eligible to vote.");
        } catch (Exception e) {
            System.out.println(e.getMessage());
            if (e.getCause()!=null) System.out.println(e.getCause().getMessage());
        } finally { System.out.println("Thank you for using our voter validation system!"); }
    }
}

public class VoterValidation {
    public static void main(String[] args) {
        Scanner sc=new Scanner(System.in);
        int age=sc.nextInt(); boolean c=sc.nextBoolean(),r=sc.nextBoolean(),f=sc.nextBoolean();
        new Voter(age,c,r,f).validateVoter(); sc.close();
    }
}

